/**
 * GELATO base v12 country products — types and loader for the registry
 * generated by scripts/countryProducts/importGelatoBaseV12.mjs from the owner
 * workbook GELLATTI_BAZA_GELATO_75_KRAJOW_v12_SYNC.xlsx.
 *
 * Exact country products are PR-ING proposals; they never create PI-ING. The six
 * base slots map only to existing Mapper PIs. PR-ING codes are issued by the
 * database at ingest — the registry carries proposal keys, not PR numbers.
 */

export const GELATO_BASE_V12_REGISTRY_SCHEMA = 'gellatti.country-products.gelato-base.registry/v1';
export const GELATO_BASE_V12_REGISTRY_ID = 'GELATO_BASE_V12';
export const GELATO_BASE_V12_REGISTRY_PATH = 'docs/country-products/gelato-base-v12/registry.json';
export const GELATO_BASE_V12_MANIFEST_PATH = 'docs/country-products/gelato-base-v12/manifest.json';
export const GELATO_BASE_V12_SOURCE_WORKBOOK = 'GELLATTI_BAZA_GELATO_75_KRAJOW_v12_SYNC.xlsx';
export const GELATO_BASE_V12_SOURCE_SHA256 =
  '09864e8602a6a7d3a89838091ce83dec7659bd2143517b5831d86f8d2f356172';

export const GELATO_BASE_SLOTS = ['MILK', 'CREAM', 'SMP', 'SUCROSE', 'DEXTROSE', 'STABILIZER'] as const;
export type GelatoBaseSlot = (typeof GELATO_BASE_SLOTS)[number];
export type ExactProductSlot = Exclude<GelatoBaseSlot, 'SUCROSE'>;
export const EXACT_PRODUCT_SLOTS: readonly ExactProductSlot[] = [
  'MILK',
  'CREAM',
  'SMP',
  'DEXTROSE',
  'STABILIZER',
];

/** Existing Mapper PIs of the 1000 g Gelato base (01_BAZA_PI). */
export const GELATO_BASE_SLOT_PI: Readonly<Record<GelatoBaseSlot, string>> = Object.freeze({
  MILK: 'PI-ING-000236',
  CREAM: 'PI-ING-000180',
  SMP: 'PI-ING-000270',
  SUCROSE: 'PI-ING-000514',
  DEXTROSE: 'PI-ING-000494',
  STABILIZER: 'PI-ING-000492',
});

/** Existing stabilizer PIs a STABILIZER slot may use (TARA is not mandatory). */
export const EXISTING_STABILIZER_PI_IDS = Object.freeze([
  'PI-ING-000492',
  'PI-ING-000472',
  'PI-ING-000475',
  'PI-ING-001384',
  'PI-ING-002114',
] as const);

export type NutrientField =
  | 'energyKcal'
  | 'fat'
  | 'saturatedFat'
  | 'carbohydrate'
  | 'sugars'
  | 'protein'
  | 'salt'
  | 'fibre';
export type NutrientValues = Readonly<Record<NutrientField, number | null>>;

export type SelectionState = 'SELECTION_CLOSED' | 'RESEARCH_OPEN' | 'BLOCKED' | 'GLOBAL_PI_READY';
export type DedupeDecision =
  | 'REUSE_EXISTING_PR'
  | 'NEW_PR_REQUIRED'
  | 'DUPLICATE_WITHIN_V12'
  | 'BLOCKED_EAN_HELD_BY_OTHER_CATALOG_ROW'
  | 'NOT_APPLICABLE_GLOBAL_PI';
export type RouteDecision =
  | 'ROUTE_ALREADY_PRESENT'
  | 'ROUTE_CREATABLE_NOW'
  | 'ROUTE_BLOCKED'
  | 'NOT_APPLICABLE_GLOBAL_PI';
export type EngineProfileExpectation =
  | 'DECLARED_PROFILE_COMPLETE'
  | 'ESTIMATED_OR_MISSING_LABEL_FIELDS'
  | 'DECLARED_BUT_DISPUTED_OPEN_CASE';
export type IdentityBasis = 'GTIN' | 'BRAND_ARTICLE_CODE' | 'LISTING_CODE' | 'NAME_HASH';

