export interface GelatoBaseRegistry {
  readonly schema: typeof GELATO_BASE_V12_REGISTRY_SCHEMA;
  readonly registryId: typeof GELATO_BASE_V12_REGISTRY_ID;
  readonly proposalNamespace: 'V12';
  readonly source: {
    readonly workbook: string;
    readonly sha256: string;
    readonly sheetsUsed: readonly string[];
    readonly openCasesV12: number | null;
  };
  readonly catalogSnapshot: {
    readonly capturedAt: string;
    readonly projectRef: string;
    readonly catalogMarketCountries: readonly string[];
  };
  readonly invariants: {
    readonly newPiCreated: number;
    readonly mapperModified: boolean;
    readonly prIngNumbersAssigned: boolean;
    readonly forcedTo75: boolean;
    readonly silentSubstitutes: number;
    readonly stabilizerTaraMandatory: boolean;
  };
  readonly base: ReadonlyArray<{
    readonly slot: GelatoBaseSlot;
    readonly grams: number;
    readonly piIngId: string;
    readonly stabilizerSlotRule: { readonly taraMandatory: false } | null;
  }>;
  readonly countries: ReadonlyArray<{
    readonly iso2: string;
    readonly iso3: string;
    readonly catalogMarketRowPresent: boolean;
  }>;
  readonly products: readonly GelatoBaseProduct[];
  readonly selections: readonly GelatoBaseSelection[];
  readonly openGaps: readonly GelatoBaseOpenGap[];
  readonly alternatives: readonly GelatoBaseAlternative[];
  readonly counts: {
    readonly products: number;
    readonly productsBySlot: Readonly<Record<ExactProductSlot, number>>;
    readonly newPiCreated: number;
    readonly proposalDecisions: Readonly<Record<string, number>>;
    readonly duplicatesPrevented: Readonly<Record<string, number>>;
    readonly openGaps: {
      readonly total: number;
      readonly byWorkbookRole: Readonly<Record<'CREAM' | 'SMP' | 'DEXTROSE' | 'TARA', number>>;
      readonly workbookHeader: Readonly<Record<'total' | 'CREAM' | 'SMP' | 'DEXTROSE' | 'TARA', number>>;
      readonly matchesWorkbookHeader: boolean;
    };
    readonly routes: Readonly<Record<string, unknown>>;
  };
  readonly sources: Readonly<Record<string, { readonly url: string }>>;
  readonly texts: Readonly<Record<string, string>>;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/** Validates the registry envelope; throws on any mismatch instead of guessing. */
export function parseGelatoBaseRegistry(raw: unknown): GelatoBaseRegistry {
  if (!isRecord(raw)) throw new Error('GELATO base registry: not a JSON object.');
  if (raw.schema !== GELATO_BASE_V12_REGISTRY_SCHEMA) {
    throw new Error(`GELATO base registry: unexpected schema ${String(raw.schema)}.`);
  }
  if (raw.registryId !== GELATO_BASE_V12_REGISTRY_ID) {
    throw new Error(`GELATO base registry: unexpected registryId ${String(raw.registryId)}.`);
  }
  const source = raw.source;
  if (!isRecord(source) || source.sha256 !== GELATO_BASE_V12_SOURCE_SHA256) {
    throw new Error('GELATO base registry: source workbook sha256 is not the pinned v12 workbook.');
  }
  for (const key of ['base', 'countries', 'products', 'selections', 'openGaps', 'alternatives']) {
    if (!Array.isArray(raw[key])) throw new Error(`GELATO base registry: ${key} must be an array.`);
  }
  if (!isRecord(raw.sources) || !isRecord(raw.texts) || !isRecord(raw.counts)) {
    throw new Error('GELATO base registry: sources, texts and counts must be objects.');
  }
  return raw as unknown as GelatoBaseRegistry;
}

export function loadGelatoBaseRegistryFromJson(json: string): GelatoBaseRegistry {
  return parseGelatoBaseRegistry(JSON.parse(json) as unknown);
}

const TEXT_ID = /^TXT-[0-9A-F]{10}$/;

/** Workbook notes longer than 120 characters are stored once in `texts`. */
export function resolveRegistryText(registry: GelatoBaseRegistry, value: string | null | undefined): string | null {
  if (value === null || value === undefined) return null;
  return TEXT_ID.test(value) ? (registry.texts[value] ?? value) : value;
}

export function sourceUrlsFor(registry: GelatoBaseRegistry, sourceIds: readonly string[]): string[] {
  return sourceIds.flatMap((id) => {
    const url = registry.sources[id]?.url;
    return url ? [url] : [];
  });
}

export function selectionFor(
  registry: GelatoBaseRegistry,
  country: string,
  slot: GelatoBaseSlot,
): GelatoBaseSelection | undefined {
  return registry.selections.find((selection) => selection.country === country && selection.slot === slot);
}

export function productFor(registry: GelatoBaseRegistry, productKey: string): GelatoBaseProduct | undefined {
  return registry.products.find((product) => product.productKey === productKey);
}

export function openGapsForRole(
  registry: GelatoBaseRegistry,
  role: GelatoBaseOpenGap['workbookRole'],
): GelatoBaseOpenGap[] {
  return registry.openGaps.filter((gap) => gap.workbookRole === role);
}
